CREATE SEQUENCE public.chromosomeaccession_seq START WITH 1 INCREMENT BY 50 NO MINVALUE NO MAXVALUE CACHE 1;

CREATE TABLE chromosomeaccession (
	id bigint CONSTRAINT chromosomeaccession_pkey PRIMARY KEY,
	chromosomename varchar(255),
	accession varchar(255),
	assemblyidentifier varchar(255),
	displayorder integer,
	datecreated timestamp without time zone,
	dateupdated timestamp without time zone,
	dbdatecreated timestamp without time zone,
	dbdateupdated timestamp without time zone,
	internal boolean DEFAULT false,
	obsolete boolean DEFAULT false,
	createdby_id bigint,
	updatedby_id bigint
);

CREATE INDEX chromosomeaccession_accession_index ON chromosomeaccession USING btree (accession);
CREATE INDEX chromosomeaccession_name_assembly_index ON chromosomeaccession USING btree (chromosomename, assemblyidentifier);

